const metrics = inputData;
const prevMetrics = inputData.previous_week || {};

// Calculate week-over-week changes
const calculateChange = (current, previous) => {
  if (!previous || previous === 0) return { value: current, change: 0, trend: 'new' };
  const change = ((current - previous) / previous) * 100;
  const trend = change > 0 ? 'up' : (change < 0 ? 'down' : 'flat');
  return { value: current, change: change.toFixed(1), trend };
};

const kpis = {
  sales: {
    new_deals: calculateChange(metrics.deals_closed, prevMetrics.deals_closed),
    pipeline_value: calculateChange(metrics.pipeline_value, prevMetrics.pipeline_value),
    avg_deal_size: calculateChange(metrics.avg_deal_size, prevMetrics.avg_deal_size),
    win_rate: calculateChange(metrics.win_rate, prevMetrics.win_rate)
  },
  customer_success: {
    active_clients: calculateChange(metrics.active_clients, prevMetrics.active_clients),
    avg_health_score: calculateChange(metrics.avg_health_score, prevMetrics.avg_health_score),
    tickets_resolved: calculateChange(metrics.tickets_resolved, prevMetrics.tickets_resolved),
    avg_resolution_hours: calculateChange(metrics.avg_resolution_hours, prevMetrics.avg_resolution_hours)
  },
  operations: {
    automation_runs: calculateChange(metrics.automation_runs, prevMetrics.automation_runs),
    automation_success_rate: calculateChange(metrics.automation_success_rate, prevMetrics.automation_success_rate),
    api_costs: calculateChange(metrics.api_costs, prevMetrics.api_costs),
    infra_costs: calculateChange(metrics.infra_costs, prevMetrics.infra_costs)
  },
  product: {
    active_users: calculateChange(metrics.active_users, prevMetrics.active_users),
    feature_adoption: calculateChange(metrics.feature_adoption, prevMetrics.feature_adoption),
    bugs_reported: calculateChange(metrics.bugs_reported, prevMetrics.bugs_reported),
    deployment_frequency: calculateChange(metrics.deployments, prevMetrics.deployments)
  }
};

return {
  kpis,
  week_start: metrics.week_start,
  week_end: metrics.week_end,
  highlights: [
    kpis.sales.new_deals.trend === 'up' ? `Sales up ${kpis.sales.new_deals.change}%` : null,
    kpis.customer_success.avg_health_score.trend === 'down' ? `Health score declining ${kpis.customer_success.avg_health_score.change}%` : null,
    kpis.operations.automation_success_rate.value > 95 ? 'Automation excellence: 95%+ success' : null
  ].filter(Boolean)
};

const kpis = inputData.kpis;

// Generate Mermaid chart for trends
const mermaidChart = `graph LR
  A[Sales] -->|${kpis.sales.new_deals.trend}| B[${kpis.sales.new_deals.change}%]
  C[CS] -->|${kpis.customer_success.avg_health_score.trend}| D[${kpis.customer_success.avg_health_score.change}%]
  E[Ops] -->|${kpis.operations.automation_success_rate.trend}| F[${kpis.operations.automation_success_rate.value}%]
  G[Product] -->|${kpis.product.active_users.trend}| H[${kpis.product.active_users.change}%]`;

// Generate ASCII chart for quick view
const asciiChart = `
Weekly KPI Trends:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Sales Pipeline:     $${kpis.sales.pipeline_value.value.toLocaleString()} ${kpis.sales.pipeline_value.trend === 'up' ? '↗' : '↘'}
Active Clients:     ${kpis.customer_success.active_clients.value} ${kpis.customer_success.active_clients.trend === 'up' ? '↗' : '↘'}
Health Score:       ${kpis.customer_success.avg_health_score.value}/100 ${kpis.customer_success.avg_health_score.trend === 'up' ? '↗' : '↘'}
Automation Success: ${kpis.operations.automation_success_rate.value}% ${kpis.operations.automation_success_rate.trend === 'up' ? '↗' : '↘'}
Active Users:       ${kpis.product.active_users.value} ${kpis.product.active_users.trend === 'up' ? '↗' : '↘'}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
`;

return {
  mermaid_chart: mermaidChart,
  ascii_chart: asciiChart
};
